// Clean-room exact bounded minimum weighted connected dominating set.
const N:usize=16;
fn put(out:[*]u8,at:usize,x:i64)void{const b:u64=@bitCast(x);for(0..8)|i|out[at+i]=@truncate(b>>@intCast(8*i));}
export fn weighted_connected_dominating_set(v:[*c]const i64,n:usize,out_opt:?[*]u8,cap:usize)i64{if(v==null||n<3||n>33||v[0]<1||v[0]>16)return -1;const count:usize=@intCast(v[0]);if(n!=1+2*count)return -1;const all=(@as(u64,1)<<@intCast(count))-1;var adj:[N]u64=@splat(0);for(0..count)|i|{const mask=v[1+i];const weight=v[1+count+i];if(mask<0 or @as(u64,@intCast(mask))>all or ((@as(u64,@intCast(mask))>>@intCast(i))&1)!=0 or weight<1 or weight>1000)return -1;adj[i]=@intCast(mask);}for(0..count)|i|{for(0..count)|j|{if(((adj[i]>>@intCast(j))&1)!=((adj[j]>>@intCast(i))&1))return -1;}}
 var best:i64=-1;var best_mask:u64=0;var mask:u64=1;while(mask<=all):(mask+=1){var dominated=mask;var cost:i64=0;for(0..count)|i|{if((mask>>@intCast(i))&1!=0){dominated|=adj[i];cost+=v[1+count+i];}}if(dominated==all){var seen=mask&(~mask+1);while(true){const old=seen;for(0..count)|i|{if((seen>>@intCast(i))&1!=0)seen|=adj[i]&mask;}if(old==seen)break;}if(seen==mask and (best<0 or cost<best or (cost==best and mask<best_mask))){best=cost;best_mask=mask;}}}if(out_opt==null or cap<16)return -2;const out=out_opt.?;var staged:[16]u8=@splat(0);put(&staged,0,best);put(&staged,8,@intCast(best_mask));@memcpy(out[0..16],staged[0..16]);return 16;}
